// ValidateAttachGuideRequestBody runs the validations defined on
// AttachGuideRequestBody
func ValidateAttachGuideRequestBody(body *AttachGuideRequestBody) (err error) {
	if body.HcTerminalID != nil {
		if utf8.RuneCountInString(*body.HcTerminalID) < 1 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.hc_terminal_id", *body.HcTerminalID, utf8.RuneCountInString(*body.HcTerminalID), 1, true))
		}
	}
	if body.Client != nil {
		if !(*body.Client == "claude" || *body.Client == "codex" || *body.Client == "antigravity" || *body.Client == "cursor" || *body.Client == "gemini" || *body.Client == "opencode") {
			err = goa.MergeErrors(err, goa.InvalidEnumValueError("body.client", *body.Client, []any{"claude", "codex", "antigravity", "cursor", "gemini", "opencode"}))
		}
	}
	if len(body.AncestorPids) > 64 {
		err = goa.MergeErrors(err, goa.InvalidLengthError("body.ancestor_pids", body.AncestorPids, len(body.AncestorPids), 64, false))
	}
	for _, e := range body.AncestorPids {
		if e < 1 {
			err = goa.MergeErrors(err, goa.InvalidRangeError("body.ancestor_pids[*]", e, 1, true))
		}
	}
	return
}

// ValidateExchangeBrowserLinkRequestBody runs the validations defined on
// ExchangeBrowserLinkRequestBody
func ValidateExchangeBrowserLinkRequestBody(body *ExchangeBrowserLinkRequestBody) (err error) {
	if body.Link == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("link", "body"))
	}
	if body.Link != nil {
		if utf8.RuneCountInString(*body.Link) < 1 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.link", *body.Link, utf8.RuneCountInString(*body.Link), 1, true))
		}
		if utf8.RuneCountInString(*body.Link) > 256 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.link", *body.Link, utf8.RuneCountInString(*body.Link), 256, false))
		}
	}
	return
}
